DESCRIPTION = "Runway Gen-4.5 model guide: 12 credits/sec pricing, 2–10s 720p clips, text-to-video and image-to-video settings, API examples, prompts and comparisons."
HERO = "Runway Gen-4.5 is a video-generation model for text-to-video and image-to-video clips. Compare 2–10-second formats, 720p output, 12 credits/second pricing and the gen4.5 API."
CANONICAL = "https://sxf.si/models/gen4-5/"
FAQS = [["What is Runway Gen-4.5?","Runway Gen-4.5 is Runway's video-generation model for making short clips from text prompts or a reference image plus a motion prompt. Its strengths include camera direction, multi-action prompts, and visual continuity."],["How much does Runway Gen-4.5 cost?","Runway Dev lists 12 credits per generated second. At $0.01 per developer API credit, a 5-second clip costs 60 credits ($0.60), and a 10-second clip costs 120 credits ($1.20), before taxes or optional output-format charges. Creative-app plan billing is separate."],["What is the Runway Gen-4.5 API model ID?","Use gen4.5 in Runway's API or SDK. The documented image-to-video endpoint also accepts text-to-video requests when promptImage is omitted."],["Does Gen-4.5 support text-to-video and image-to-video?","Yes. Text-to-video accepts a written scene and motion description. Image-to-video uses an input still image to define appearance and composition, with text describing how the image should animate."],["What video durations and resolution does Gen-4.5 support?","Runway's creator documentation lists 2 to 10 seconds, a standard 720p output and 24 or 25 frames per second in the web app. Aspect-ratio options depend on the mode."],["What aspect ratios are available for Gen-4.5?","Runway lists 16:9 and 9:16 for text-to-video, while image-to-video supports landscape, portrait, square and widescreen formats, including 16:9, 9:16, 1:1, 4:3, 3:4 and 21:9."],["How should I write a Gen-4.5 prompt?","For text-to-video, describe the subject, setting, action, camera movement and desired timing. For image-to-video, let the input still establish the visual scene and emphasize movement and temporal changes in the prompt."],["Is Runway Gen-4.5 cheaper than Gen-4 Turbo?","No. Runway Dev lists Gen-4.5 at 12 credits per second and Gen-4 Turbo at 5 credits per second. Gen-4 Turbo is the lower-cost choice for iterations; output quality should be judged on your own test prompts."],["Can I generate a 60-second video with one Gen-4.5 request?","Not through the standard 2–10-second clip-generation modes documented for Gen-4.5. Longer sequences require producing and editing or combining shorter shots."],["Can I export ProRes or HDR with Gen-4.5?","Runway documents optional professional output formats. ProRes or PNG sequence adds 5 credits per second; HDR or other 10-bit formats have a separate surcharge. Availability and pricing can depend on plan, output dimensions and format."]]
SECTIONS = "\n        <section class=\"model-deep-section\" id=\"gen45-overview\" data-runway-gen45-guide>\n          <div class=\"model-section-head\"><p class=\"eyebrow\">MODEL OVERVIEW</p><h2>What is Runway Gen-4.5?</h2></div>\n          <p><strong>Runway Gen-4.5 is a video-generation model</strong> that turns written directions into moving scenes or animates a supplied image. The model is designed for creators who want to direct the subject, camera movement and timing of short shots instead of relying on an undirected animation. It supports both <strong>text-to-video</strong> and <strong>image-to-video</strong> workflows in Runway's web app and developer tools.</p>\n          <p><strong>Quick answer:</strong> Runway documents 2–10-second clips, standard 720p output, 24 or 25 fps in the creator interface, and a base generation rate of 12 credits per second. The Runway Dev API model identifier is <code>gen4.5</code>. Video generation is billed by output duration, not language-model input/output tokens.</p>\n          <nav class=\"model-related-links\" aria-label=\"Jump to Gen-4.5 details\">\n            <a href=\"#gen45-pricing\"><span>VIDEO PRICING</span><strong>Credits and example costs</strong><b>↗</b></a>\n            <a href=\"#gen45-modes\"><span>VIDEO MODES</span><strong>Text-to-video vs image-to-video</strong><b>↗</b></a>\n            <a href=\"#gen45-api\"><span>DEVELOPER API</span><strong>Model ID and code example</strong><b>↗</b></a>\n          </nav>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"gen45-specifications\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">TECHNICAL SPECIFICATIONS</p><h2>Runway Gen-4.5 specs: resolution, duration, FPS and formats.</h2><p>These are video-generation limits, not text-LLM context-window figures.</p></div>\n          <div class=\"model-capability-grid\">\n            <article><span>MODEL ID</span><h3><code>gen4.5</code></h3><p>The identifier to use in Runway's developer API and SDK.</p></article>\n            <article><span>CLIP LENGTH</span><h3>2–10 seconds</h3><p>Runway's standard Gen-4.5 creator workflow generates short clips; longer edited videos require multiple shots.</p></article>\n            <article><span>STANDARD OUTPUT</span><h3>720p video</h3><p>Runway's creator guide lists 24 fps and 25 fps frame-rate options. Upscaling and professional output formats are separate workflows.</p></article>\n            <article><span>TEXT-TO-VIDEO RATIOS</span><h3>16:9 and 9:16</h3><p>Use 1280×720 for landscape or 720×1280 for portrait in the documented text-only workflow.</p></article>\n            <article><span>IMAGE-TO-VIDEO RATIOS</span><h3>Six common formats</h3><p>16:9, 9:16, 1:1, 4:3, 3:4 and 21:9, including 960×960 square and 1584×672 ultra-wide formats. Consult current endpoint input limits for precise accepted pixel dimensions.</p></article>\n            <article><span>INPUT / OUTPUT</span><h3>Text + optional image → video</h3><p>Text-to-video begins with a written prompt; image-to-video animates a still image using a motion prompt. A token context-window or text output cap is not published for this service.</p></article>\n          </div>\n          <p>Source: <a href=\"https://help.runwayml.com/hc/en-us/articles/46974685288467-Creating-with-Gen-4-5\" target=\"_blank\" rel=\"noopener noreferrer\">Runway's Gen-4.5 creator specifications</a> and <a href=\"https://docs.dev.runwayml.com/assets/inputs/\" target=\"_blank\" rel=\"noopener noreferrer\">Runway Dev input and aspect-ratio requirements</a>. Availability may differ between the web product and developer endpoints.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"gen45-pricing\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">MODEL PRICING</p><h2>Runway Gen-4.5 pricing: credits and cost per video.</h2></div>\n          <p>Runway Dev charges <strong>12 credits per second</strong> for Gen-4.5. The developer portal sells credits at <strong>$0.01 each</strong>, making the base API equivalent <strong>$0.12 per second</strong>. The catalog's <strong>$7.20 per generated minute</strong> is only a unit conversion: a normal Gen-4.5 generation is a 2–10-second clip, not a one-minute output.</p>\n          <div class=\"model-capability-grid\">\n            <article><span>2-SECOND CLIP</span><h3>24 credits ≈ $0.24</h3><p>Smallest listed standard clip duration. Formula: 2 seconds × 12 credits per second.</p></article>\n            <article><span>5-SECOND CLIP</span><h3>60 credits ≈ $0.60</h3><p>Useful baseline for testing camera movements and short product shots. Formula: 5 × 12 credits.</p></article>\n            <article><span>10-SECOND CLIP</span><h3>120 credits ≈ $1.20</h3><p>Upper end of the standard single-clip range. Formula: 10 × 12 credits.</p></article>\n          </div>\n          <p><strong>Important:</strong> these are developer API credit equivalents before taxes or extra format costs. Runway's creative-app subscription credits and Explore Mode operate under their own plan terms; don't treat an Unlimited web subscription as unlimited API usage.</p>\n          <p><strong>Optional formats:</strong> Runway Dev lists a ProRes/PNG-sequence surcharge of 5 credits per second, and a 10-bit/HDR surcharge starting at 20 credits per second (higher for outputs larger than four megapixels). These apply on top of the model's 12-credit base rate. Verify that the requested format is supported by your endpoint and account.</p>\n          <p>Official rates: <a href=\"https://docs.dev.runwayml.com/guides/pricing/\" target=\"_blank\" rel=\"noopener noreferrer\">Runway Dev API pricing</a>.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"gen45-modes\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">VIDEO GENERATION MODES</p><h2>Runway Gen-4.5 text-to-video vs image-to-video.</h2></div>\n          <div class=\"model-capability-grid\">\n            <article><span>TEXT TO VIDEO</span><h3>Describe the entire shot</h3><p>Provide the subject, environment, action, framing, lighting and camera motion in words. Start here for exploring fresh concepts, scene designs and cinematic establishing shots without a reference image.</p><p><strong>Example prompt:</strong> A wide shot of a tram moving through a rainy neon-lit city at dusk. The camera tracks beside it as reflections glide across the wet pavement, then gently pushes toward the driver.</p></article>\n            <article><span>IMAGE TO VIDEO</span><h3>Animate a chosen first frame</h3><p>Upload or pass a still image to anchor the subject and composition. Then focus the written prompt on motion and timing: what changes, how the subject moves and how the camera behaves. This is useful for products, character continuity and art-directed shots.</p><p><strong>Example motion prompt:</strong> The camera makes a slow clockwise orbit around the bottle. Condensation droplets roll down the glass as the background lights softly drift out of focus.</p></article>\n          </div>\n          <p><strong>Prompting distinction:</strong> text-to-video needs visual and motion detail; image-to-video typically needs much less re-description of the supplied image and more instruction about movement. Runway's <a href=\"https://help.runwayml.com/hc/en-us/articles/42460036199443-Text-to-Video-Prompting-Guide\" target=\"_blank\" rel=\"noopener noreferrer\">text-to-video guide</a> and <a href=\"https://help.runwayml.com/hc/en-us/articles/48324313115155-Image-to-Video-Prompting-Guide\" target=\"_blank\" rel=\"noopener noreferrer\">image-to-video guide</a> explain both approaches.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"gen45-prompting\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">PROMPT ENGINEERING</p><h2>How to write better Gen-4.5 prompts.</h2></div>\n          <div class=\"model-caveat-list\">\n            <div><span>01</span><p><strong>Specify visible actions.</strong> Replace vague goals like “a dramatic video” with concrete subject movements, physical interactions and environmental changes. In text-to-video, establish the shot first; in image-to-video, use the supplied frame as the starting point.</p></div>\n            <div><span>02</span><p><strong>Direct the camera.</strong> Use film terms such as locked camera, dolly-in, orbit, overhead tracking or handheld movement, and specify direction and pacing. Avoid stacking several conflicting movements into a short clip.</p></div>\n            <div><span>03</span><p><strong>Give events a sequence.</strong> For more complex action, describe a clear beginning, transition and end. A 10-second shot has more room for multiple beats than a 2-second shot.</p></div>\n            <div><span>04</span><p><strong>Iterate one variable at a time.</strong> Keep the subject and framing fixed while testing a different camera path or motion speed; this makes failures easier to diagnose and helps you compare outputs.</p></div>\n            <div><span>05</span><p><strong>Use a clean reference frame.</strong> Image-to-video depends heavily on the input image's framing and subject clarity. Describe the desired animation directly instead of trying to rewrite the appearance of an already-defined scene.</p></div>\n          </div>\n          <p>These are practical workflow recommendations grounded in Runway's <a href=\"https://academy.runwayml.com/guides/prompting-guide\" target=\"_blank\" rel=\"noopener noreferrer\">Gen-4.5 prompting academy</a> and <a href=\"https://help.runwayml.com/hc/en-us/articles/47313504791059-Camera-Terms-Prompts-Examples\" target=\"_blank\" rel=\"noopener noreferrer\">camera-direction examples</a>. Results vary by scene, prompt and input frame.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"gen45-api\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">RUNWAY DEVELOPER API</p><h2>How to use Gen-4.5 through the API.</h2></div>\n          <p>Runway's documented SDK and API use the exact model identifier <code>gen4.5</code>. Create an image-to-video task with a <code>promptImage</code> and a <code>promptText</code>; omit the image for text-only video generation. The generation endpoint creates an asynchronous task: collect the task ID and retrieve the completed output using the API or the SDK's waiting helper.</p>\n          <div class=\"model-caveat-list\">\n            <div><span>01</span><p><strong>Set up Runway Dev:</strong> create an API project and store your secret in <code>RUNWAYML_API_SECRET</code>, never in browser-side source code.</p></div>\n            <div><span>02</span><p><strong>Pick the mode:</strong> use <code>model: \"gen4.5\"</code>, <code>promptText</code>, <code>duration</code> and <code>ratio</code>. For image-to-video, add <code>promptImage</code> with an accepted image URL or upload reference.</p></div>\n            <div><span>03</span><p><strong>Submit and monitor:</strong> POST to <code>/v1/image_to_video</code>, receive a task ID, and fetch the result when the task completes. Handle failures and retries in production rather than assuming synchronous output.</p></div>\n          </div>\n          <p><strong>Minimal text-to-video request:</strong></p>\n          <pre style=\"white-space:pre-wrap;overflow-wrap:anywhere;overflow-x:auto\"><code>curl -X POST https://api.dev.runwayml.com/v1/image_to_video \\\n  -H \"Authorization: Bearer $RUNWAYML_API_SECRET\" \\\n  -H \"X-Runway-Version: 2024-11-06\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\n    \"model\": \"gen4.5\",\n    \"promptText\": \"A wide shot of clouds crossing snowy peaks. Slow dolly forward.\",\n    \"ratio\": \"1280:720\",\n    \"duration\": 5\n  }'</code></pre>\n          <p>For image-to-video, supply a valid <code>promptImage</code> field as well. The request structure is based on Runway's <a href=\"https://docs.dev.runwayml.com/guides/using-the-api/\" target=\"_blank\" rel=\"noopener noreferrer\">official API quickstart</a>. Validate output sizes, account access and current API-version requirements before deploying.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"gen45-comparisons\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">ALTERNATIVES AND TRADE-OFFS</p><h2>Gen-4.5 vs Gen-4 Turbo: cost and workflow.</h2></div>\n          <div class=\"model-capability-grid\">\n            <article><span>RUNWAY GEN-4.5</span><h3>12 credits per second</h3><p>Choose when you want to test Runway's newer prompt-adherence and complex motion capabilities, with both text-to-video and image-to-video options.</p></article>\n            <article><span>RUNWAY GEN-4 TURBO</span><h3>5 credits per second</h3><p>A lower-cost Runway alternative for rapid image-to-video iterations and simpler creative experiments. Gen-4 Turbo is not a direct substitute for all Gen-4.5 modes; compare each mode and use case before selecting.</p></article>\n          </div>\n          <p>At 5 seconds, base Runway Dev pricing works out to approximately <strong>$0.60 for Gen-4.5</strong> or <strong>$0.25 for Gen-4 Turbo</strong>. This is a price comparison, not a claim about measured visual quality. For other vendors, explore the <a href=\"/models/kling-3-0/\">Kling 3.0 model reference</a> or the <a href=\"/compare/\">SXF model comparison hub</a>.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"gen45-use-cases\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">PRACTICAL APPLICATIONS</p><h2>Best use cases and limitations of Runway Gen-4.5.</h2></div>\n          <div class=\"model-capability-grid\">\n            <article><span>MARKETING</span><h3>Short campaign footage</h3><p>Create controlled product shots, atmosphere clips and pre-production concepts where camera movement and visual style are important.</p></article>\n            <article><span>FILM AND DESIGN</span><h3>Storyboards and previsualization</h3><p>Explore camera moves, scene pacing and alternative shots before committing to a production plan or combining clips in an editor.</p></article>\n            <article><span>CREATOR WORKFLOWS</span><h3>Animate art-directed images</h3><p>Start from a designed still frame and test one motion concept at a time, preserving the look established by the reference image.</p></article>\n          </div>\n          <p><strong>Know the limits:</strong> standard generations are short clips; individual outputs are not complete feature-length scenes. Complex scenes may require iteration and editing. Creative-app plan access is separate from API usage, and advanced export options carry additional conditions or costs. Runway's creator guide publishes video output settings, but not an LLM-style context window or knowledge cutoff.</p>\n        </section>\n"
FAQ_HTML = "\n        <section class=\"model-deep-section\" id=\"gen45-faq\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">COMMON QUESTIONS</p><h2>Runway Gen-4.5 FAQs.</h2></div>\n          <div class=\"model-caveat-list\">\n            <div><span>01</span><p><strong>What is Runway Gen-4.5?</strong> Runway Gen-4.5 is Runway's video-generation model for making short clips from text prompts or a reference image plus a motion prompt. Its strengths include camera direction, multi-action prompts, and visual continuity.</p></div>\n            <div><span>02</span><p><strong>How much does Runway Gen-4.5 cost?</strong> Runway Dev lists 12 credits per generated second. At $0.01 per developer API credit, a 5-second clip costs 60 credits ($0.60), and a 10-second clip costs 120 credits ($1.20), before taxes or optional output-format charges. Creative-app plan billing is separate.</p></div>\n            <div><span>03</span><p><strong>What is the Runway Gen-4.5 API model ID?</strong> Use gen4.5 in Runway's API or SDK. The documented image-to-video endpoint also accepts text-to-video requests when promptImage is omitted.</p></div>\n            <div><span>04</span><p><strong>Does Gen-4.5 support text-to-video and image-to-video?</strong> Yes. Text-to-video accepts a written scene and motion description. Image-to-video uses an input still image to define appearance and composition, with text describing how the image should animate.</p></div>\n            <div><span>05</span><p><strong>What video durations and resolution does Gen-4.5 support?</strong> Runway's creator documentation lists 2 to 10 seconds, a standard 720p output and 24 or 25 frames per second in the web app. Aspect-ratio options depend on the mode.</p></div>\n            <div><span>06</span><p><strong>What aspect ratios are available for Gen-4.5?</strong> Runway lists 16:9 and 9:16 for text-to-video, while image-to-video supports landscape, portrait, square and widescreen formats, including 16:9, 9:16, 1:1, 4:3, 3:4 and 21:9.</p></div>\n            <div><span>07</span><p><strong>How should I write a Gen-4.5 prompt?</strong> For text-to-video, describe the subject, setting, action, camera movement and desired timing. For image-to-video, let the input still establish the visual scene and emphasize movement and temporal changes in the prompt.</p></div>\n            <div><span>08</span><p><strong>Is Runway Gen-4.5 cheaper than Gen-4 Turbo?</strong> No. Runway Dev lists Gen-4.5 at 12 credits per second and Gen-4 Turbo at 5 credits per second. Gen-4 Turbo is the lower-cost choice for iterations; output quality should be judged on your own test prompts.</p></div>\n            <div><span>09</span><p><strong>Can I generate a 60-second video with one Gen-4.5 request?</strong> Not through the standard 2–10-second clip-generation modes documented for Gen-4.5. Longer sequences require producing and editing or combining shorter shots.</p></div>\n            <div><span>10</span><p><strong>Can I export ProRes or HDR with Gen-4.5?</strong> Runway documents optional professional output formats. ProRes or PNG sequence adds 5 credits per second; HDR or other 10-bit formats have a separate surcharge. Availability and pricing can depend on plan, output dimensions and format.</p></div>\n          </div>\n        </section>\n"
SOURCES = ["https://docs.dev.runwayml.com/guides/using-the-api/","https://docs.dev.runwayml.com/guides/pricing/","https://docs.dev.runwayml.com/assets/inputs/","https://help.runwayml.com/hc/en-us/articles/46974685288467-Creating-with-Gen-4-5","https://help.runwayml.com/hc/en-us/articles/42460036199443-Text-to-Video-Prompting-Guide","https://help.runwayml.com/hc/en-us/articles/48324313115155-Image-to-Video-Prompting-Guide","https://academy.runwayml.com/guides/prompting-guide","https://help.runwayml.com/hc/en-us/articles/47313504791059-Camera-Terms-Prompts-Examples"]
MARKER = '<section class="model-deep-section"><div class="model-section-head"><p class="eyebrow">CAVEATS</p>'


def _replace_meta(page, key, value):
    pattern = r'(<meta (?:name|property)="' + re.escape(key) + r'" content=")[^"]*(" />)'
    page, count = re.subn(pattern, lambda m: m.group(1) + escape(value, quote=True) + m.group(2), page, count=1)
    if count != 1:
        raise ValueError("Gen-4.5 page missing meta field: " + key)
    return page


def enrich_runway_gen45_page(page):
    """Return a complete, indexable model reference while preserving its URL."""
    if 'data-runway-gen45-guide' in page:
        return page
    if f'<link rel="canonical" href="{CANONICAL}"' not in page:
        raise ValueError("Gen-4.5 canonical URL drift")
    page, count = re.subn(r"<title>.*?</title>", "<title>" + escape(TITLE) + "</title>", page, count=1)
    if count != 1:
        raise ValueError("Gen-4.5 title missing")
    for key, value in (
        ("description", DESCRIPTION),
        ("og:title", TITLE),
        ("og:description", DESCRIPTION),
        ("twitter:title", TITLE),
        ("twitter:description", DESCRIPTION),
    ):
        page = _replace_meta(page, key, value)

    old_h1 = "<h1>Runway Gen-4.5<br><span>verified model reference.</span></h1>"
    if page.count(old_h1) != 1:
        raise ValueError("Gen-4.5 hero heading changed")
    page = page.replace(old_h1, "<h1>Runway Gen-4.5<br><span>Video model, pricing &amp; API.</span></h1>", 1)

    old_hero = "<p>Runway API text-to-video and image-to-video model for cinematic camera motion, prompt-controlled shots and production video sequences.</p>"
    if page.count(old_hero) != 1:
        raise ValueError("Gen-4.5 hero description changed")
    page = page.replace(old_hero, "<p>" + escape(HERO) + "</p>", 1)

    old_stats = (
        '<div><strong>Not published</strong><span>context not published</span></div>\n'
        '          <div><strong>Not published</strong><span>max output</span></div>'
    )
    new_stats = (
        '<div><strong>2–10s</strong><span>clip duration</span></div>\n'
        '          <div><strong>720p</strong><span>standard resolution</span></div>'
    )
    if page.count(old_stats) != 1:
        raise ValueError("Gen-4.5 generic hero facts changed")
    page = page.replace(old_stats, new_stats, 1)

    schema_match = re.search(r'(<script type="application/ld\+json">)(.*?)(</script>)', page, re.DOTALL)
    if not schema_match:
        raise ValueError("Gen-4.5 page missing JSON-LD")
    data = json.loads(schema_match.group(2))
    article = next((node for node in data["@graph"] if node.get("@type") == "TechArticle"), None)
    if article is None:
        raise ValueError("Gen-4.5 page missing TechArticle")
    article["headline"] = TITLE.removesuffix(" | SXF / AI")
    article["description"] = DESCRIPTION
    article["citation"] = SOURCES
    article["mainEntityOfPage"] = {"@type": "WebPage", "@id": CANONICAL}
    article["publisher"] = {"@type": "Organization", "name": "SXF / AI", "url": "https://sxf.si/"}
    data["@graph"].append({
        "@type": "FAQPage",
        "@id": CANONICAL + "#faq",
        "url": CANONICAL + "#faq",
        "mainEntity": [
            {"@type": "Question", "name": question, "acceptedAnswer": {"@type": "Answer", "text": answer}}
            for question, answer in FAQS
        ],
    })
    jsonld = json.dumps(data, ensure_ascii=False, separators=(",", ":"))
    page = page[:schema_match.start(2)] + jsonld + page[schema_match.end(2):]

    if page.count(MARKER) != 1:
        raise ValueError("Gen-4.5 standard caveats section changed")
    page = page.replace(MARKER, SECTIONS + FAQ_HTML + "\n\n        " + MARKER, 1)
    return page
